  switch (key) {
    case 'ArrowUp':
      controls.gas = value;
      return true;
    case 'ArrowDown':
      controls.brake = value;
      return true;
    case 'ArrowLeft':
      controls.left = value;
      return true;
    case 'ArrowRight':
      controls.right = value;
      return true;
  }
  return false;

