//  УРОК 3, ШАГ 3. МОЗГ МАШИНЫ: как из показаний сенсоров получить решение
// ════════════════════════════════════════════════════════════════
//
//  inputs — массив чисел, по порядку (при 7 сенсорах — 19 чисел):
//           s1…s7   сенсоры слева направо: 0 — ничего не видно, 1 — стена или машина вплотную;
//           v       скорость;
//           s1′…s7′ те же сенсоры мгновение назад — видно, приближается ли стена;
//           зн      дорожный знак, мимо которого едем: -1 — «налево», 1 — «направо», 0 — знака нет;
//           m1…m3   заметки: что мозг сам себе «записал» на прошлом шаге (на старте нули).
//  brain  — веса и пороги. brain.layers[k].weights[i][j] — сила связи
//           от нейрона i к нейрону j следующего слоя, biases[j] — порог нейрона j.
//  Ответ  — 7 чисел от 0 до 1: [газ, тормоз, влево, вправо, m1, m2, m3].
//           Первые 4 — кнопки пульта, последние 3 — новые заметки: на следующем шаге они придут на вход.
//
//  Все варианты ниже отличаются только тем, что нейрон делает со своей суммой.
//  Вариант выбирается на вкладке «Я учу». Обученные веса подходят к любому.

import { sigmoid } from '../engine/utils.ts';

// Прямой проход: слой за слоем считаем для каждого нейрона сумму «вход × вес»
// и отдаём её функции activate(sum, bias, isOutput) — она решает, что нейрон «скажет» дальше.
// isOutput = true для последнего слоя (газ, тормоз, влево, вправо и заметки m1…m3).
export function feedForward(inputs, brain, activate) {
  let values = inputs;
  const trace = [inputs];
  brain.layers.forEach((layer, k) => {
    const isOutput = k === brain.layers.length - 1;
    const next = [];
    for (let j = 0; j < layer.biases.length; j++) {
      let sum = 0;
      for (let i = 0; i < values.length; i++) {
        sum += values[i] * layer.weights[i][j];
      }
      next.push(activate(sum, layer.biases[j], isOutput));
    }
    values = next;
    trace.push(values);
  });
  feedForward.lastTrace = trace;
  return values;
}
// Последний проход по всем слоям — по нему «Я учу» подсвечивает нейроны на схеме
feedForward.lastTrace = null;

export const thinkVariants = {
  noBias: {
    title: 'Без порогов',
    hint: 'Нейрон срабатывает, если сумма больше нуля, порогов нет. Загадка: что сделает машина, когда сенсоры ничего не видят?',
    think(inputs, brain) {
      return feedForward(inputs, brain, (sum) => (sum > 0 ? 1 : 0));
    },
  },

  step: {
    title: 'Ступенька',
    hint: 'Классика: сумма больше порога — 1, иначе 0. Едет, но руль только «до упора» или «никак».',
    think(inputs, brain) {
      return feedForward(inputs, brain, (sum, bias) => (sum > bias ? 1 : 0));
    },
  },

  smooth: {
    title: 'Плавный',
    hint: 'Вместо ступеньки — плавные кривые: ответ — сила нажатия от 0 до 1. Учится дольше, зато рулит мягче.',
    think(inputs, brain) {
      // Внутри сети tanh (от -1 до 1), на выходе сигмоида (от 0 до 1).
      // Множители 2 и 3 — «крутизна» кривой. Попробуй поменять в своём варианте.
      return feedForward(inputs, brain, (sum, bias, isOutput) =>
        isOutput ? sigmoid(3 * (sum - bias)) : Math.tanh(2 * (sum - bias)),
      );
    },
  },

  winner: {
    title: 'Победитель забирает всё',
    hint: 'Считаем плавно, но жмём только одну кнопку — самую сильную. Где это хорошо, а где плохо?',
    think(inputs, brain) {
      const out = feedForward(inputs, brain, (sum, bias, isOutput) =>
        isOutput ? sigmoid(3 * (sum - bias)) : Math.tanh(2 * (sum - bias)),
      );
      const buttons = out.slice(0, 4); // заметки (после кнопок) не соревнуются — их передаём как есть
      const best = buttons.indexOf(Math.max(...buttons));
      return out.map((v, i) => (i < 4 ? (i === best ? 1 : 0) : v));
    },
  },

  mine: {
    title: 'Мой вариант',
    hint: 'Придумай свой. Правила: столько чисел от 0 до 1, сколько выходов (4 кнопки и заметки), без Math.random, быстро.',
    think(inputs, brain) {
      // TODO: придумай свой способ думать. Идеи:
      //  • другая функция: Math.tanh(sum - bias) * 0.5 + 0.5
      //  • «мёртвая зона»: если сумма чуть-чуть больше порога — жать вполсилы
      //  • поправить ответ после feedForward: не жать газ и тормоз одновременно
      //  • скорость — сразу после сенсоров: inputs[7] при 7 сенсорах. Можно сбрасывать газ, если едем слишком быстро
      //  • сравни inputs[3] и inputs[11] (сенсор 4 сейчас и мгновение назад): стена приближается — тормози
      return feedForward(inputs, brain, (sum, bias) => (sum > bias ? 1 : 0));
    },
  },
};

export const DEFAULT_THINK = 'smooth'; // в опыте рой с ним учится надёжнее всего (tools/swarm-check.mjs)
`,mutate:`// ════════════════════════════════════════════════════════════════
//  УРОК 3, ШАГ 2. МУТАЦИЯ — как получить новое поколение из лучшей машины
// ════════════════════════════════════════════════════════════════
//
//  brain — копия мозга лучшей машины. Меняй его прямо на месте, возвращать ничего не нужно.
//    brain.layers[k].weights[i][j] — числа от -1 до 1
//    brain.layers[k].biases[j]     — числа от -1 до 1
//  rate  — сила мутации от 0 до 1 (слайдер на вкладке «Учится само»).
//          0 — ничего не менять, 1 — полностью случайный мозг.
//
//  Как сейчас: каждое число с вероятностью rate чуть сдвигаем случайным шумом, остальные не трогаем.
//  Так ребёнок похож на родителя, но где-то чуть другой: хорошее не теряется, новое пробуется.
//  В опыте (tools/swarm-check.mjs) так рой учится куда надёжнее, чем если «тянуть» к случайному все числа сразу.

import { randomGauss } from '../engine/utils.ts';

const STEP = 0.4; // насколько сдвигаем выбранное число: обычно меньше чем на STEP

export function mutate(brain, rate) {
  const nudge = (w) => (Math.random() < rate ? w + randomGauss() * STEP : w);
  for (const layer of brain.layers) {
    layer.biases = layer.biases.map(nudge);
    layer.weights = layer.weights.map((row) => row.map(nudge));
  }
}
`,fitness:`// ════════════════════════════════════════════════════════════════
//  УРОК 3, ШАГ 1. ФИТНЕС — за что хвалить машину
// ════════════════════════════════════════════════════════════════
//
//  Вызывается для каждой машины, когда поколение закончилось.
//  Чем больше число, тем машина «лучше». Лучшая станет родителем следующего поколения.
//
//  car = {
//    progress     — сколько пикселей проехала вдоль трассы, все круги вместе (лучший результат)
//    trackLength  — длина всего заезда: три круга
//    progressPct  — то же в процентах, 0..100
//    finished     — доехала до финиша
//    crashed      — разбилась (в бордюр или в машину)
//    hitCar       — разбилась именно о машину
//    stalled      — заглохла или крутилась на месте
//    ticks        — сколько тиков ехала (60 тиков = 1 секунда гонки)
//    avgSpeed     — средняя скорость, px за тик
//    topSpeed     — максимальная скорость
//    wiggle       — сколько дёргала руль (чем больше, тем сильнее виляла)
//  }
//
//  Как сейчас: за расстояние, а доехавшим — бонус, и чем быстрее, тем больше.
//  Машина оптимизирует ровно то, что ты посчитал, а не то, что ты имел в виду:
//  без бонуса за время рою всё равно, ползти через медленную зону или нет.

export function fitness(car) {
  let score = car.progress;
  if (car.finished) score += 20000 - car.ticks; // на три круга дают меньше 20 тыс. тиков, так что бонус всегда больше нуля
  return score;
}
`,crossover:`// ════════════════════════════════════════════════════════════════
//  БОНУС. КРОССОВЕР — ребёнок от двух родителей
// ════════════════════════════════════════════════════════════════
//
//  mom, dad — мозги двух лучших машин поколения (одинаковой формы).
//    brain.layers[k].weights[i][j] — связь нейрона i → нейрон j следующего слоя
//    brain.layers[k].biases[j]     — порог нейрона j
//  Вернуть нужно НОВЫЙ мозг той же формы. Родителей менять нельзя.
//  После скрещивания ребёнка ещё немного мутируют — это делает приложение.
//
//  Включается на вкладке «Учится само»: «Родителей: 2».
//
//  Как сейчас: целыми нейронами. Для каждого нейрона одна монетка решает, чьи ВСЕ его входящие связи
//  и порог он получит — мамины или папины. Нейрон — цельная «идея» («справа близко — рули влево»), её не рвём.

export function crossover(mom, dad) {
  return {
    layers: mom.layers.map((layer, k) => {
      const fromMom = layer.biases.map(() => Math.random() < 0.5); // монетка на каждый нейрон следующего слоя
      const other = dad.layers[k];
      return {
        weights: layer.weights.map((row, i) => row.map((w, j) => (fromMom[j] ? w : other.weights[i][j]))),
        biases: layer.biases.map((b, j) => (fromMom[j] ? b : other.biases[j])),
      };
    }),
  };
}
